import urllib.request, urllib.parse, urllib.error
BASE = "http://160.202.254.160:15880/"
PROXY = {"http": "http://127.0.0.1:12001", "https": "http://127.0.0.1:12001"}
op = urllib.request.build_opener(urllib.request.ProxyHandler(PROXY))

def dec(b):
    return b.decode("gb18030", "replace")

def get(path="", data=None):
    url = BASE + path
    if data is not None:
        data = urllib.parse.urlencode(data).encode()
    try:
        with op.open(url, data=data, timeout=20) as r:
            return r.status, dec(r.read()), dict(r.headers)
    except urllib.error.HTTPError as e:
        return e.code, dec(e.read()), dict(e.headers)

